// Kart görselleri: elle tasarlanmış SVG sahneleri. Çıktı site/assets/gorsel/<tur>/<ad>.svg. Çağıran: ortak.js (her derlemede yazılır).
// Ortak dil: 480x300, sektör renginde koyu degrade zemin, nokta deseni, açık renk nesneler. Zemin kendi içinde koyu olduğu için açık ve koyu temada aynı okunur (<img> sayfa değişkenini göremez).
// Stok fotoğraf, marka logosu yok. Yeni araç veya program eklenince buraya sahne yazılır; server/test/site-kabuk.test.js eksik sahneyi düşürür.
const fs = require('fs'); const path = require('path');
const OUT = path.join(__dirname, '..', 'assets', 'gorsel');

// ---------- Renk ----------
const rgb = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
const k = (h, a) => { const [r, g, b] = rgb(h); const t = a < 0 ? 0 : 255; const p = Math.abs(a); return '#' + [r, g, b].map((v) => Math.round(v + (t - v) * p).toString(16).padStart(2, '0')).join(''); }; // a>0 açar, a<0 koyulaştırır
let A = '#2563eb'; // sahnenin rengi, sar() ve nesneler okur
const a1 = () => k(A, 0.45); const a2 = () => k(A, 0.72); const a3 = () => k(A, 0.86); const ad = () => k(A, -0.25);

// ---------- Yapı taşları ----------
const n = (x) => +(+x).toFixed(1);
const r = (x, y, w, h, f = '#fff', rx = 6, e = '') => `<rect x="${n(x)}" y="${n(y)}" width="${n(w)}" height="${n(h)}" rx="${rx}" fill="${f}"${e ? ' ' + e : ''}/>`;
const c = (x, y, R, f = '#fff', e = '') => `<circle cx="${n(x)}" cy="${n(y)}" r="${n(R)}" fill="${f}"${e ? ' ' + e : ''}/>`;
const p = (d, f = '#fff', e = '') => `<path d="${d}" fill="${f}"${e ? ' ' + e : ''}/>`;
const l = (d, s = '#fff', w = 6, e = '') => `<path d="${d}" fill="none" stroke="${s}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"${e ? ' ' + e : ''}/>`;
const t = (x, y, s, z = 22, f = '#fff', an = 'middle') => `<text x="${n(x)}" y="${n(y)}" font-family="Arial,Helvetica,sans-serif" font-size="${z}" font-weight="700" text-anchor="${an}" fill="${f}">${s}</text>`;
const g = (x, y, s, ic) => `<g transform="translate(${n(x)} ${n(y)}) scale(${s})">${ic}</g>`;
const dn = (x, y, a, ic) => `<g transform="rotate(${a} ${n(x)} ${n(y)})">${ic}</g>`;
const gol = (x, y, w, h, rx = 10) => r(x, y + 8, w, h, '#000', rx, 'opacity=".22"'); // yumuşak gölge yerine katman: dosya küçük kalır
const kag = (x, y, w, h, rx = 10, f = '#fff') => gol(x, y, w, h, rx) + r(x, y, w, h, f, rx);
const sat = (x, y, w, m = 3, ar = 14, f = '#c9d5e6', b = 6) => Array.from({ length: m }, (_, i) => r(x, y + i * ar, i === m - 1 ? w * 0.62 : w, b, f, b / 2)).join('');
const belge = (x, y, w, h, o = {}) => { const m = Math.min(16, w * 0.22); return gol(x, y, w, h, 6) + p(`M${x + 6} ${y}H${x + w - m}L${x + w} ${y + m}V${y + h - 6}a6 6 0 0 1-6 6H${x + 6}a6 6 0 0 1-6-6V${y + 6}a6 6 0 0 1 6-6z`, o.f || '#fff') + p(`M${x + w - m} ${y}V${y + m}H${x + w}z`, a2()) + (o.m === 0 ? '' : sat(x + 12, y + (o.ust || 22), w - 24, o.m || 4, o.ar || 13, '#c9d5e6', 5)); };
const ok = (x1, y1, x2, y2, s = '#fff', w = 7) => { const a = Math.atan2(y2 - y1, x2 - x1); const u = 14; return l(`M${n(x1)} ${n(y1)}L${n(x2)} ${n(y2)}M${n(x2 - u * Math.cos(a - 0.6))} ${n(y2 - u * Math.sin(a - 0.6))}L${n(x2)} ${n(y2)}L${n(x2 - u * Math.cos(a + 0.6))} ${n(y2 - u * Math.sin(a + 0.6))}`, s, w); };
const rozet = (x, y, R, s, f = '#ffd166', tf = '#1b2a41', z) => c(x, y + 3, R, '#000', 'opacity=".22"') + c(x, y, R, f) + t(x, y + (z || R * 0.8) * 0.36, s, z || R * 0.8, tf);
const tik = (x, y, R = 16, f = '#22c55e') => c(x, y + 3, R, '#000', 'opacity=".2"') + c(x, y, R, f) + l(`M${x - R * 0.45} ${y}l${R * 0.32} ${R * 0.34} ${R * 0.6}-${R * 0.68}`, '#fff', R * 0.26);
const carpi = (x, y, R = 16, f = '#ef4444') => c(x, y + 3, R, '#000', 'opacity=".2"') + c(x, y, R, f) + l(`M${x - R * 0.36} ${y - R * 0.36}l${R * 0.72} ${R * 0.72}m0-${R * 0.72}l-${R * 0.72} ${R * 0.72}`, '#fff', R * 0.26);
const foto = (x, y, w, h) => kag(x, y, w, h, 8) + r(x + 6, y + 6, w - 12, h - 12, a2(), 5) + c(x + w * 0.72, y + h * 0.3, h * 0.1, '#ffd166') + p(`M${n(x + 6)} ${n(y + h - 6)}l${n(w * 0.3)} ${n(-h * 0.5)} ${n(w * 0.2)} ${n(h * 0.28)} ${n(w * 0.14)} ${n(-h * 0.16)} ${n(w * 0.36 - 12)} ${n(h * 0.38)}z`, ad());
const qr = (x, y, s, on = '#14233a', arka = '#fff') => { const m = 13; const b = s / m; let d = ''; const dolu = (i, j) => (i * 7 + j * 13 + i * j * 3) % 5 < 2; for (let j = 0; j < m; j++) for (let i = 0; i < m; i++) { const koseA = (i < 4 && j < 4) || (i > 8 && j < 4) || (i < 4 && j > 8); if (!koseA && dolu(i, j)) d += `M${n(x + i * b)} ${n(y + j * b)}h${n(b)}v${n(b)}h${n(-b)}z`; } const goz = (a, e) => r(a, e, b * 3.4, b * 3.4, on, 3) + r(a + b * 0.7, e + b * 0.7, b * 2, b * 2, arka, 2) + r(a + b * 1.15, e + b * 1.15, b * 1.1, b * 1.1, on, 1); return kag(x - 12, y - 12, s + 24, s + 24, 12, arka) + p(d, on) + goz(x, y) + goz(x + s - b * 3.4, y) + goz(x, y + s - b * 3.4); };
const barkod = (x, y, w, h, f = '#14233a') => { const G = [3, 1, 2, 1, 4, 1, 1, 2, 3, 1, 1, 3, 2, 1, 4, 2, 1, 1, 3, 2, 1, 2, 1, 3, 1, 1, 2, 4, 1, 2]; const top = G.reduce((a, b) => a + b, 0); let o = 0; let d = ''; G.forEach((b, i) => { const u = (b / top) * w; if (i % 2 === 0) d += `M${n(x + o)} ${y}h${n(u)}v${h}h${n(-u)}z`; o += u; }); return p(d, f); };
const takvim = (x, y, w, h, o = {}) => { const hf = h * 0.26; let i = ''; for (let j = 0; j < 3; j++) for (let e = 0; e < 4; e++) i += r(x + 12 + e * ((w - 24) / 4), y + hf + 12 + j * ((h - hf - 18) / 3), (w - 24) / 4 - 6, (h - hf - 18) / 3 - 6, o.on && o.on.includes(e + j * 4) ? (o.renk || A) : '#dfe7f2', 3); return kag(x, y, w, h, 10) + p(`M${x} ${y + hf}v${-hf + 10}a10 10 0 0 1 10-10h${w - 20}a10 10 0 0 1 10 10v${hf - 10}z`, o.ust || A) + r(x + w * 0.24, y - 7, 8, 18, '#fff', 4) + r(x + w * 0.7, y - 7, 8, 18, '#fff', 4) + i; };
const hesap = (x, y, w, h) => { let i = ''; for (let j = 0; j < 4; j++) for (let e = 0; e < 3; e++) i += r(x + 12 + e * ((w - 24) / 3), y + h * 0.36 + j * ((h * 0.64 - 8) / 4), (w - 24) / 3 - 6, (h * 0.64 - 8) / 4 - 6, e === 2 ? A : '#dfe7f2', 3); return kag(x, y, w, h, 12, '#22324a') + r(x + 12, y + 12, w - 24, h * 0.22, '#d9f7e4', 4) + i; };
const grafik = (x, y, w, h, o = {}) => { const v = o.v || [0.25, 0.45, 0.35, 0.65, 0.55, 0.9]; const b = (w - 24) / v.length; return kag(x, y, w, h, 10) + v.map((u, i) => r(x + 14 + i * b, y + h - 12 - u * (h - 30), b - 8, u * (h - 30), i === v.length - 1 ? (o.son || A) : a1(), 3)).join(''); };
const para = (x, y, R = 22, f = '#ffd166') => c(x, y + 3, R, '#000', 'opacity=".2"') + c(x, y, R, f) + c(x, y, R * 0.78, 'none', `stroke="#d9a520" stroke-width="2"`) + t(x, y + R * 0.38, '₺', R * 1.05, '#7a5a06');
const kisi = (x, y, s = 1, f = '#fff') => c(x, y, 13 * s, f) + p(`M${n(x - 22 * s)} ${n(y + 44 * s)}c0-${n(20 * s)} ${n(10 * s)}-${n(28 * s)} ${n(22 * s)}-${n(28 * s)}s${n(22 * s)} ${n(8 * s)} ${n(22 * s)} ${n(28 * s)}z`, f);
const saat = (x, y, R = 34, o = {}) => c(x, y + 4, R, '#000', 'opacity=".2"') + c(x, y, R, '#fff') + c(x, y, R - 6, 'none', `stroke="${A}" stroke-width="3"`) + l(`M${x} ${y}V${y - R * 0.55}M${x} ${y}L${x + R * 0.4} ${y + R * 0.2}`, o.f || '#22324a', 5);
const kalkan = (x, y, s = 1, f = '#fff') => p(`M${x} ${y - 46 * s}l${n(40 * s)} ${n(14 * s)}v${n(34 * s)}c0 ${n(30 * s)}-${n(20 * s)} ${n(46 * s)}-${n(40 * s)} ${n(56 * s)}c-${n(20 * s)}-${n(10 * s)}-${n(40 * s)}-${n(26 * s)}-${n(40 * s)}-${n(56 * s)}v-${n(34 * s)}z`, f);
const kilit = (x, y, s = 1, f = '#ffd166') => r(x - 24 * s, y - 6 * s, 48 * s, 38 * s, f, 7) + l(`M${n(x - 14 * s)} ${n(y - 6 * s)}v-${n(10 * s)}a${n(14 * s)} ${n(14 * s)} 0 0 1 ${n(28 * s)} 0v${n(10 * s)}`, f, 6 * s) + c(x, y + 10 * s, 5 * s, '#7a5a06');
const buyutec = (x, y, R = 34) => l(`M${n(x + R * 0.72)} ${n(y + R * 0.72)}L${n(x + R * 1.5)} ${n(y + R * 1.5)}`, '#ffd166', 10) + c(x, y, R, 'rgba(255,255,255,.22)', `stroke="#fff" stroke-width="8"`);
const arac = (x, y, s = 1, f = '#fff', cam = a1()) => g(x, y, s, p('M-92 18c-6 0-10-4-10-10v-14c0-8 6-14 14-15l26-5 24-26c5-5 11-8 18-8h52c7 0 13 3 18 8l22 24 30 6c8 2 14 8 14 16v14c0 6-4 10-10 10z', f) + p('M-48-20l18-20c2-2 5-3 8-3h22v23zM8-43h22c3 0 6 1 8 3l18 20H8z', cam) + c(-58, 18, 19, '#1b2a41') + c(-58, 18, 8, '#c9d5e6') + c(62, 18, 19, '#1b2a41') + c(62, 18, 8, '#c9d5e6'));
const anahtar = (x, y, s = 1, f = '#ffd166') => g(x, y, s, c(0, 0, 18, f) + c(0, 0, 7, ad()) + r(14, -5, 52, 10, f, 3) + r(50, 3, 8, 12, f, 2) + r(36, 3, 8, 9, f, 2));
const kutu = (x, y, s = 1, f = '#e8b26a') => g(x, y, s, r(-40, -36, 80, 72, f, 5) + r(-40, -36, 80, 18, k(f, -0.16), 5) + r(-9, -36, 18, 30, '#fff', 0, 'opacity=".55"'));
const yuzde = (x, y, z = 46, f = '#fff') => t(x, y + z * 0.36, '%', z, f);
const pdf = (x, y) => r(x, y, 46, 22, '#ef4444', 4) + t(x + 23, y + 16, 'PDF', 14);
const kalem = (x, y, s = 1, f = '#ffd166') => g(x, y, s, r(-5, -44, 10, 68, f, 2) + p('M-5 24h10l-5 14z', '#22324a'));
const baloncuk = (x, y, R) => c(x, y, R, 'rgba(255,255,255,.28)', 'stroke="#fff" stroke-width="2"');

